{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "For the \"delay compensation\" cost, is the delay measured as the number of quarters a unit is late relative to its contract quarter (so a unit produced in Q2 to satisfy a Q1 contract incurs 1 quarter of delay)?",
    "Is this cost applied to every unit that is not delivered in its contract quarter, or only to units that are ultimately delivered late?"
  ],
  "rationale": "The response contains two semantically independent questions: one asking for the definition of the delay metric (how many quarters late) and another asking for the scope of application (all late units vs. only those ultimately delivered late). A user could answer the first without answering the second."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can production in a later quarter be used to satisfy demand from an earlier quarter (i.e., is backordering allowed), or must all demand for a given quarter be satisfied by production in that same quarter or earlier?"
  ],
  "rationale": "The response asks a single clarification question regarding the policy on backordering and demand satisfaction timing."
}

